import{_ as r,a as l}from"./chunks/d1dea96f33b3a6adbd52.CU_IFVbc.js";import{_ as t,C as i,o,c as n,j as e,a as s,E as h,a6 as d}from"./chunks/framework.CnPv4DE1.js";const y=JSON.parse('{"title":"漫长步行的力量（每天1.5万步改变了我的生活）","description":"","frontmatter":{"title":"漫长步行的力量（每天1.5万步改变了我的生活）","originalTitle":"The Power Of Long Walks (15,000 Steps A Day Changed My Life)","date":"2024-06-07","originalUrl":"https://thedankoe.com/letters/the-power-of-long-walks-daily-walks-will-change-your-life/","minutes":12,"sourceHash":"0f9be55680b6ec4f8e511dae6fe55e5006c79737f5fad75051faf19f17ed3aad","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-power-of-long-walks-daily-walks-will-change-your-life/"}]]},"headers":[],"relativePath":"letters/the-power-of-long-walks-daily-walks-will-change-your-life.md","filePath":"letters/the-power-of-long-walks-daily-walks-will-change-your-life.md"}'),f={name:"letters/the-power-of-long-walks-daily-walks-will-change-your-life.md"};function c(u,p,m,g,k,b){const a=i("ArticleMeta");return o(),n("div",null,[p[0]||(p[0]=e("h1",{id:"漫长步行的力量-每天1-5万步改变了我的生活",tabindex:"-1"},[s("漫长步行的力量（每天1.5万步改变了我的生活） "),e("a",{class:"header-anchor",href:"#漫长步行的力量-每天1-5万步改变了我的生活","aria-label":'Permalink to "漫长步行的力量（每天1.5万步改变了我的生活）"'},"​")],-1)),h(a),p[1]||(p[1]=d('<p><a href="https://www.youtube.com/embed/lU1wgq-2Isg?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><img src="'+r+'" alt=""></p><p>我以前<em><strong>非常讨厌</strong></em>走路。</p><p>我不是说我只是讨厌悠闲地散步。</p><p>我讨厌走路去任何地方。我就是懒惰的代名词……也许用“高效”这个词更好。我喜欢去健身房，喜欢折腾我的副业，但除此之外，你要么能在沙发上、床上找到我，要么就是看我瘫在办公椅上打电子游戏。我一直都是那种只做最低限度努力的人，这在很大程度上倒也总能让我以某种方式受益。</p><p>我会找各种借口避免走路，或者干脆开车去。</p><p>交代一下背景，当 Juul 电子烟流行起来时，我开始使用尼古丁（没错，我就是那种不懂事、盲目跟风的小屁孩之一）。最终，为了在深度工作中保持专注，这种尼古丁使用习惯转变成了使用 Zyns。Zyns 是一种不含烟草的尼古丁袋，现在非常火。</p><p>2019年的某一天，我突然意识到，滥用尼古丁正在损害我给予他人的注意力。我总是感到疲倦。在交谈中我也说得不多。如果有一段时间没吸一口，我脑子里就只能想这件事。</p><p>（好奇的朋友们听好了，我现在仍在使用尼古丁，因为它有各种好处，而且我经常会一次停用一两周作为缓冲）。</p><p>大概在那个时候，不知道怎么回事，我在社交媒体上看到了一篇关于走路好处的帖子。内容大概是关于“为了夏天减脂”以及用走路代替无休止的有氧运动。</p><p>一切就这么顺理成章，我决定直接彻底戒掉尼古丁。每当烟瘾犯了，我就决定去快走10分钟，并嚼口香糖代替。</p><p>最初的几次散步很无聊，但确实有效。戒掉尼古丁其实相当容易，而且我总能用“我在燃烧卡路里”这个事实来为这点小痛苦找到正当理由。走路成了让我<em>感觉</em>自己在疯狂刷脂的一种方式。这让我想要走得更多。</p><p>在一个月的时间里，我每天都走满了那被奉为神明的10,000步。</p><p>结果是我彻底爱上了走路。</p><p>5年来，我没有一天的步数低于1万步。当我住在奥斯汀（Austin）时，我平均每天走2万到2.5万步。现在我平均每天走1.5万步左右。</p><p>考虑到我谈论步行的重要性有多频繁，有些人甚至会说我的名字已经成了“走路”的代名词。妈的，就连我和丹尼·米兰达（Danny Miranda）做的一期播客，名字都叫“<a href="https://youtu.be/3Rwr8cK9aQ0?si=-b7UG8JUtVEgLEIu" target="_blank" rel="noreferrer">Dan Koe – The King Of Walking.</a>”</p><p>就像查尔斯·达尔文（Charles Darwin）和史蒂夫·乔布斯（Steve Jobs）将散步视为他们生活和工作中的关键部分一样，我也发现了这一点。</p><p>有人问：“如果你每天花好几个小时走路，你怎么完成工作？”</p><p>我的回答是，去读读纳西姆·尼古拉斯·塔勒布（NN Taleb）的《反脆弱》（Anti-Fragile）第7章，或者读读我的<a href="/letters/zero-to-1-million-as-a-one-person-business-while-working-2-4-hours-per-day">四小时工作日</a>哲学。</p><p>简而言之，除非必要，我尽量不<em>做</em>任何事，因为这是大自然内置的从噪音中过滤信号的机制。太多人整天苦干却一无所获，因为他们淹没在那些毫无意义的琐事中了。</p><p>而且，如果不是因为走路，你可能根本不会在读这封信。</p><p>我的想法会有所不同。我的内容会有所不同。我的身体会有所不同。我的身份也会有所不同。</p><p>我想和你分享：</p><ol><li><p>走路最纯粹的力量，让你有足够的“理由”坚持这个习惯。</p></li><li><p>如何将走路变成一场游戏，从而让你自然而然地养成这个习惯。</p></li></ol><p>我希望通过这封信，用一个简单的习惯来改变你的生活。</p><p>我们开始吧。</p><h2 id="头脑、身体、精神与商业——全方位的习惯" tabindex="-1">头脑、身体、精神与商业——全方位的习惯 <a class="header-anchor" href="#头脑、身体、精神与商业——全方位的习惯" aria-label="Permalink to &quot;头脑、身体、精神与商业——全方位的习惯&quot;">​</a></h2><p><img src="'+l+'" alt=""></p><p>我希望能把这个观点传达清楚：</p><p>你每天的时间只有这么多。</p><p>意思是，你能养成的习惯是有限的。</p><p>这也意味着，你选择执行的习惯至关重要，因为它们塑造了你的未来并影响着你的生活质量。</p><p>大多数人无法掌控自己选择的习惯，因此他们的生活走在一条并非由自己设定的轨迹上，改变自己也变得越来越难。</p><p>习惯不仅是生理上的，也是心理上的。</p><p>你通过刷手机来分散自己的注意力。</p><p>你的注意力持续时间正在缩短，因为你的大脑已经习惯了每30秒接收一次新奇的信息。</p><p>所以，你无法专注于有意义的对话。你无法专注于建立一家企业。你甚至无法专注于穿上鞋子去健身房。</p><p>你的大脑几乎对所有事情都做出条件反射，用的全是别人植入你脑海里的梗和碎片信息。你对任何事都无法认真对待。你把任何有价值的事情都当成一个笑话。与此同时，你感到沮丧和绝望，却找不到出路，因为你的大脑被困在肤浅的表面上跳跃，根本看不到解决方案。</p><p>你大多数问题的解决方案就是：</p><p>你必须夺回你的注意力，以便你能执行新的习惯。</p><p>你必须执行新的习惯，因为你只能选择少数几个。</p><p>你选择的习惯必须具备高杠杆（high leverage）、高影响力，并且能带来高度享受。</p><p>你选择的习惯能让你重新把注意力集中在生命的深度上。</p><p>你的注意力放在哪里，就会如何重塑你的大脑，造就你的为人，并决定你的未来。</p><p>走路作为一种习惯，涵盖了所有层面：头脑、身体、精神和商业。</p><p>让我来告诉你怎么做。</p><h3 id="走路即冥想" tabindex="-1">走路即冥想 <a class="header-anchor" href="#走路即冥想" aria-label="Permalink to &quot;走路即冥想&quot;">​</a></h3><p>我以前对冥想持怀疑态度。</p><p>我原以为这是专门为嬉皮士和新时代狂热者准备的，他们以为自己能引导某种能量来变得更强大，就像在《降世神通》（Avatar the Last Airbender）里那样。</p><p>事实证明，就像大多数我讨厌的事情一样，我只是不了解冥想究竟是什么。</p><p>冥想是释放你头脑的行为。</p><p>冥想是减少你对思想的执念。</p><p>冥想是与现实融为一体的练习，而不是去期待未来或执着于过去。</p><p>换句话说，通过持续的冥想练习，生活会变得更好，因为你正真正活在当下。</p><p>大多数人没有意识到他们的生活有多么肤浅。他们在自己的脑海中兜圈子，制造出根本不存在的问题，并失控地陷入深度焦虑和不堪重负的状态。</p><p>他们的生活被充满压力的过去情境所支配，这影响了他们对未来的感知。昨天对你大吼大叫的老板让你今天害怕去上班。昨天写得很烂的内容让你担心明天也写不完，于是你继续把这种情况投射到未来：你无法完成任务，你的副业失败了，你开始制定B计划——却没有意识到，你正在用思想创造那个现实，因为你的行动自然会跟上。</p><p>你将自己困在一种思维狭隘的痛苦状态中，而你唯一的出路就是通过冥想来重塑你的大脑。</p><p>问题是，我总是无法养成打坐冥想的习惯。我经常会忘记，或者我发现如果我不把写作等其他工作放在每天早上的第一件事来做，这些工作就会大受影响。</p><p>我们稍后再谈如何通过走路进行冥想。</p><h3 id="走路为了健康" tabindex="-1">走路为了健康 <a class="header-anchor" href="#走路为了健康" aria-label="Permalink to &quot;走路为了健康&quot;">​</a></h3><p>这点不难理解。</p><p><strong>走路 = 增加卡路里消耗。</strong></p><p>我不知道这有多真实，但我读到过，无论是走还是跑相同的距离，燃烧的卡路里是一样的。所以，如果一个人走一英里，另一个人跑一英里，他们燃烧的热量是相等的。我敢肯定两者之间有微小的差异。主要的区别在于你跑完这段距离的速度。</p><p>我喜欢走路，因为在跑步时我无法真正地去听、读、捕捉灵感或写作。</p><p>因此，如果你苦于减肥，走路是一个可以养成的可持续习惯。</p><p><strong>待在户外 = 阳光和隔绝蓝光。</strong></p><p>蓝光不仅会损害你的睡眠，还会破坏你的健康并引发慢性疾病。</p><p>大多数人都听过安德鲁·休伯曼（Andrew Huberman）关于早晨第一件事就是晒太阳的建议，但就连他也承认这只是冰山一角。</p><p>我不打算在这里讲得太深，因为有整本书的信息量需要囊括，但我会给你推荐一些可以深入了解的人物：</p><p><a href="https://x.com/Outdoctrination" target="_blank" rel="noreferrer">Analyze &amp; Optimize</a></p><p><a href="https://x.com/DrJackKruse" target="_blank" rel="noreferrer">Jack Kruse</a></p><p><a href="https://x.com/Grimhood" target="_blank" rel="noreferrer">Grimhood</a></p><p>阳光对你健康的重要性超乎你的想象，你之所以可能害怕它，是因为你认为自己会得皮肤癌（而实际上阳光有助于逆转皮肤癌——这是众多的<a href="https://x.com/zaidkdahhaj/status/1798381439479943612" target="_blank" rel="noreferrer">入门信息</a>和<a href="https://x.com/zaidkdahhaj/status/1796966480640381210" target="_blank" rel="noreferrer">另一篇信息</a>，你可以根据自己的好奇心深入了解）。</p><p>大多数人被中心化教条严重洗脑，认为要防晒保护自己，而实际上防晒正是当今许多疾病的主要诱因之一。</p><p>为了说明这能达到什么效果，拿我举例，我是你见过最苍白的人。我以前总是害怕阳光，高中暑假做救生员时，我每天得重新涂4到5次防晒霜。</p><p>有了正确的饮食和方案，我现在在阳光下根本不会晒伤。</p><p>我每天走大约1.5万到2万步，大部分是在亚利桑那州（Arizona）紫外线指数高达9到10的酷暑中进行的，我却没有被晒伤。</p><p>那些有兴趣深入了解这一点的人，可以开始搜索诸如“如何建立阳光老茧（solar callus）”之类的信息，并从那里研究你不曾了解过的概念。</p><p>说了这么多，请明白我的想法并不等同于他们的想法。我只是分享我发现有用的信息，而不是要你们采纳他们的全部意识形态。我不完全同意他们说的很多话，但这并不意味着我不能从其中受益。</p><h3 id="走路为了创造力" tabindex="-1">走路为了创造力 <a class="header-anchor" href="#走路为了创造力" aria-label="Permalink to &quot;走路为了创造力&quot;">​</a></h3><p>如果我能把我在写作和作为创作者（creator）上的成功归功于一件事，那就是走路。</p><p>对我来说，走路就是我的创意时间块。在这里我会：</p><ul><li>听有声书和 YouTube 上的长篇讲座（<a href="http://actualized.org/" target="_blank" rel="noreferrer">actualized.org</a> 是我的最爱）</li><li>阅读实体书（没错，我早上散步时会带上一本书，边走边读）。</li><li>记下我想写下来的点子（使用这个<a href="https://7daystogeniusideas.com/" target="_blank" rel="noreferrer">免费课程中的天才创意流程</a>）</li><li>在沉默中行走，让大脑去解决问题，缓解压力，或理清我的目标或愿景。</li></ul><p>不要轻视“创意时间块”这个概念。</p><p>你为你的深度工作安排了生产力时间块，但为了让它们产生任何独特或原创的贡献，它们需要通过创意时间块来平衡。</p><p>换句话说，如果你不投入时间通过思考和解决问题来培养和发展创意，你的工作就很难达到卓越的境地。</p><p>因为面对现实吧……</p><p>你可能难以养成阅读或冥想的习惯，因为你困在了充斥着各种干扰的室内。而如果你本意是想阅读或构思，却选择了做专注型的工作，那么这也算是一种分心，说明你缺乏纪律性。</p><p>当你走出去散步时，你唯一的选择就是去执行你所说过要做的事。</p><h2 id="将散步游戏化-养成令人愉悦的散步习惯" tabindex="-1">将散步游戏化，养成令人愉悦的散步习惯 <a class="header-anchor" href="#将散步游戏化-养成令人愉悦的散步习惯" aria-label="Permalink to &quot;将散步游戏化，养成令人愉悦的散步习惯&quot;">​</a></h2><p>为什么我们会对电子游戏如此上瘾？</p><ol><li>有明确的目标层级（如何获胜 + 任务）</li><li>有明确的进度反馈（升级 + 里程碑）</li><li>有规则来收拢你的注意力并消除干扰</li><li>有教程让你快速上手游戏</li><li>有根据你的技能水平设定的挑战，这样你就不会感到焦虑或不知所措</li></ol><p>简而言之，电子游戏之所以让人上瘾，是因为它们将我们推入心流状态。</p><p>心流状态的特点是绝对的清晰。零干扰。那种纯粹的进步感是世界上任何其他感觉都无法比拟的……而且你可以通过大多数习惯来进入这种状态，尤其是散步。</p><p>你知道你需要做什么、如何去做、何时去做，而且这并不容易也不为大众所熟知，所以它很有意义。</p><p>新鲜感带来的额外多巴胺也不是什么坏事。</p><p>所以，为了养成这个新的散步习惯，我认为明智的做法是将其变成一场游戏。这就是我在不知不觉中所做的事情。4年后，我不用再担心超重、不健康，也不用担心想不出能让我比大多数人更快建立企业的创意点子。</p><h3 id="第一步-明确你为什么散步" tabindex="-1">第一步：明确你为什么散步 <a class="header-anchor" href="#第一步-明确你为什么散步" aria-label="Permalink to &quot;第一步：明确你为什么散步&quot;">​</a></h3><p>愿景和反愿景。</p><p>我总是谈论这些，因为它们真他*的太重要了。</p><p>如果你不能把你采取的每一个行动与你理想的生活方式对齐，你就是迷失的、盲目的、被程序化设定的。你没有在自己做决定，你的大脑很容易在不知不觉中顺从他人的意愿。</p><p>深入思考一下，散步作为一个整体性的习惯是如何彻底改变你的生活的。</p><ul><li>你想要戒除坏习惯带来的好处吗？散步可以成为那个坏习惯的替代品。</li><li>你想在工作中更有创造力吗？你是否总是难以写出或想出能改变你未来的点子？你能看出一次简单的散步将如何改变你的人生方向吗？</li><li>你想减掉10磅脂肪、晒黑一点，并收获持续阳光照射带来的好处吗？如果你的心理健康一团糟，这难道不值得一试吗？</li></ul><p>列出现在生活中你不喜欢的一切事物。</p><p>以此为基础，列出1年后你希望在生活中拥有的一切。</p><p>然后，仔细思考每天走10000步以上能如何帮助你实现这些。</p><h3 id="第二步-设定每日目标并将其分解" tabindex="-1">第二步：设定每日目标并将其分解 <a class="header-anchor" href="#第二步-设定每日目标并将其分解" aria-label="Permalink to &quot;第二步：设定每日目标并将其分解&quot;">​</a></h3><p>所有行为都始于一个有意识或无意识的目标。</p><p>你采取的每一个行动都可以映射到你正在追求的一个目标上。问题是：那个目标是你自己设定的吗？还是你被媒体、父母、老师和朋友悄悄植入了程序？</p><p>一个简单的习惯也没有什么不同。</p><p>设定一个每日目标，从小处着手。</p><p>我觉得10000步对大多数人来说是可行的，只要他们能够实事求是地重新安排生活并确定优先级。你<em>可以</em>早点起床，早点睡觉，并告诉你的配偶这对你很重要——这件“散步”的小事带来的好处将溢出到你的整个生活。</p><p>如果一天走10000步让你感到焦虑，就像在电子游戏中那样把目标定低一点。如果10000步是100级，那就把2000步当作1级，然后再从那里往上增加。</p><p>现在，把这个目标分解为你每次散步的子目标。</p><ul><li>你打算在一次散步中全部走完吗？</li><li>你打算把它们分摊开来吗？</li><li>散步时你打算走哪条路线？</li><li>你打算走到某个特定的地标或位置吗？</li><li>你打算走到当地的咖啡馆去进行专注工作吗？</li></ul><p>通过坚持这些目标，为你的新习惯带来清晰度，直到一个月左右后它们变得自动化。</p><h3 id="第三步-为散步制定规则" tabindex="-1">第三步：为散步制定规则 <a class="header-anchor" href="#第三步-为散步制定规则" aria-label="Permalink to &quot;第三步：为散步制定规则&quot;">​</a></h3><p>现在，为了进一步收拢你的注意力并增加散步的乐趣，我们需要制定规则。</p><p>如果不这么做，你的大脑就会倾向于抱怨。</p><p>“我不喜欢散步。”</p><p>“外面太热/太冷了呜呜，我需要我那个舒适的空调房。”</p><p>“我不住在一个适合步行的城市。”</p><p>全都是借口。即使你不想散步，你也可以去走走。你进桑拿房的时候，就不会在乎里面热不热。你的期望和限制性信念正在毁掉你的潜力。</p><p>这里有一些你可以玩的规则：</p><ul><li>走路时绝不踩在路面的裂缝上。</li><li>从一本书或有声书中带着3个写作点子回来。</li><li>让身体两侧各晒15分钟太阳。</li><li>交替进行5-10分钟的散步冥想和5-10分钟的学习。</li><li>读完书的一章或一门课的一个模块。</li><li>写一小节你的新闻通讯，或者写几篇内容（就像我在 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a> 中教的那样）</li></ul><p>试一个看看。</p><h3 id="第四步-去散步-并设定一个触发条件" tabindex="-1">第四步：去散步（并设定一个触发条件） <a class="header-anchor" href="#第四步-去散步-并设定一个触发条件" aria-label="Permalink to &quot;第四步：去散步（并设定一个触发条件）&quot;">​</a></h3><p>散步是最简单的部分。</p><p>让自己出门去散步才是最难的部分。</p><p>如果你有一个触发条件，比如当我想戒烟又对尼古丁产生渴望时，就可以利用那个时刻立刻走到外面开始散步。</p><p>如果你没有任何动力或触发条件，你需要引导你的大脑去采取当下阻力最小的行动。</p><p>你能走到衣橱前去拿你的鞋吗？</p><p>如果这太困难了，问问自己，为什么你甚至无法控制自己的身体去走几英尺远。</p><p>同时，把它进一步分解。</p><p>你能走到你的房间吗？</p><p>不能？</p><p>你起码能站起来吧？</p><p>不能？</p><p>好吧，动动你的脚。</p><p>还是不能？</p><p>我无话可说了。</p><p>到了这一步，谁也救不了你了。</p><p>（如果你确实因为没有双腿或双腿残废而无法行走，请无视我，因为我确信你会告诉这些人，他们对哪怕只是能走路的能力都不懂感恩）。</p><p>就是这样。</p><p>开始散步吧。</p><p>周末愉快。</p><p>– Dan</p><hr><p><a href="/en/letters/the-power-of-long-walks-daily-walks-will-change-your-life">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',149))])}const q=t(f,[["render",c]]);export{y as __pageData,q as default};
